/* The lines of a PEM above joined into one []byte from a. */
static inline Slice tls_test_pem(Alloc *a, const char *const *lines) {
    Int n = 0;
    for (const char *const *l = lines; *l != NULL; l++)
        n += (Int)strlen(*l);
    Slice b = slice_make(a, TYPE_BYTE, 0, n);
    if (b.p == NULL)
        panic_str(BURROW_S("tls_test_pem: out of memory"));
    for (const char *const *l = lines; *l != NULL; l++) {
        Int ln = (Int)strlen(*l);
        memcpy((Byte *)b.p + b.len, *l, (size_t)ln);
        b.len += ln;
    }
    return b;
}

/* parseTestCert, with the certificate and its key from a. */
static inline TlsCertificate parse_test_cert(Alloc *a, const char *const *cert_pem,
                                             const char *const *key_pem) {
    TlsCertificate cert = {0};
    Slice rest;
    PemBlock *block = pem_decode(a, tls_test_pem(a, cert_pem), &rest);
    if (block == NULL)
        panic_str(BURROW_S("failed to parse certificate PEM"));
    cert.certificate = slice_make(a, TYPE_BYTES, 1, 1);
    if (cert.certificate.p == NULL)
        panic_str(BURROW_S("parse_test_cert: out of memory"));
    ((Slice *)cert.certificate.p)[0] = block->bytes;
    cert.leaf = x509_parse_certificate(a, block->bytes, NULL);
    if (cert.leaf == NULL)
        panic_str(BURROW_S("failed to parse certificate"));
    if (cert.leaf->public_key_algorithm != X509_UNKNOWN_PUBLIC_KEY_ALGORITHM) {
        block = pem_decode(a, tls_test_pem(a, key_pem), &rest);
        if (block == NULL)
            panic_str(BURROW_S("failed to parse key PEM"));
        cert.private_key = x509_parse_pkcs8_private_key(a, block->bytes, NULL);
        if (cert.private_key.t == NULL)
            panic_str(BURROW_S("failed to parse private key"));
    }
    return cert;
}

